3635	\begin{theorem}[Quarter powers and square-root deficits]
3636		\label{thm:qld-quarter-power-deficit-bound}
3637		\lean{MIPStarRE.QPBT.rpow_quarter_nonneg}
3638		\lean{MIPStarRE.QPBT.sqrt_deficit_bound_le}
3639		\leanok
3640		For every $x\in\R$, the real quarter power $x^{1/4}$ is nonnegative.
3641		If $m\geq1$ and $\delta_P,\delta_Q\geq0$, then
3642		\[
3643		 \sqrt{2\sqrt{4m^2\delta_P}+2\sqrt{4\delta_Q}}
3644		 \leq2\sqrt m\bigl(\delta_P^{1/4}+\delta_Q^{1/4}\bigr).
3645		\]
3646		These are formalization-only scalar estimates used in the real-part bounds
3647		of Claims 17-2 and 17-3.
3648	\end{theorem}
3649	\begin{proof}
3650		\leanok
3651		Separate the two nonnegative summands under the outer square root, simplify
3652		the square roots of $4m^2\delta_P$ and $4\delta_Q$, and compare the remaining
3653		factor $2$ with $2\sqrt m$.
3654	\end{proof}
