3656	\begin{theorem}[Polynomial error after conditioning]
3657		\label{thm:qld-conditioned-polynomial-bound}
3658		\lean{MIPStarRE.QPBT.exists_conditioned_polynomial_bound}
3659		\leanok
3660		Let $p(x)=\poly(x)$, let $f(x,y)=\poly(x,y)$, and fix $c\ge1$.
3661		There exists $g(x,y)=\poly(x,y)$ such that for every
3662		$\eps,\rho\ge0$ and every $\mu\in[1/2,1]$,
3663		\[
3664			\min\left\{1,\,
3665				\mu f\left(\rho,
3666					\frac{8p(\eps)+c(\eps+\sqrt{\eps})}{\mu}\right)+\rho
3667			\right\}
3668			\le g(\eps,\rho).
3669		\]
3670		This scalar estimate supports the pasting substitution in the proof of
3671		Lemma~\ref{lem:qld-xz-lines}. The interval for $\mu$ is an explicit
3672		hypothesis of this auxiliary estimate.
3673	\end{theorem}
3674	\begin{proof}
3675		\leanok
3676		Choose $A,r,B,s,t$ as in the polynomial bounds above, and set
3677		$\alpha=\min\{r,1/2\}$, $\beta=\min\{s,1\}$, and $L=8A+2c$.
3678		For $0\le\eps,\rho\le1$, the numerator in the argument of $f$ is at
3679		most $L\eps^\alpha$, and division by $\mu\ge1/2$ costs at most a
3680		factor of two. The polynomial bound on $f$, together with $\mu\le1$,
3681		therefore gives the required inequality with
3682		\[
3683			g(\eps,\rho)=\bigl(B(1+(2L)^t)+1\bigr)
3684				\bigl(\eps^{\alpha t}+\rho^\beta\bigr).
3685		\]
3686		If either $\eps>1$ or $\rho>1$, this function is at least one, which
3687		bounds the minimum. All its exponents are positive.
3688	\end{proof}
